-- 2026-11-18 每日收录：出柜模拟器、Untrusted、Evolve、Underrun、Space Huggers，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('coming-out-simulator', '出柜模拟器', 'Coming Out Simulator 2014', 'chugui moniqi chuguimoniqi coming out simulator nicky case', 'Nicky Case', '', '', NULL, '', 0, 2014, 'story', '["互动叙事","故事"]', 260, 0.08, 'story', 'https://ncase.me/cos/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '一个半真半假的故事，关于半真半假的话', '你要在晚餐桌上应对父母的追问：坦白、撒谎，还是含糊其辞。每个选择都会被记住，大约 20 分钟。', 'At the dinner table, you decide whether to tell your parents the truth, lie, or hedge. The game remembers each choice. About 20 minutes.', '由 Nicky Case 制作，以公共领域发布。原页托管在 ncase.me/cos，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Nicky Case and released into the public domain. Hosted at ncase.me/cos; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/coming-out-simulator.jpg', 1280, 800, 'center', '["assets/posters/coming-out-simulator.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -28, 1794967200000, 'A half-true story about half-truths.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('untrusted', 'Untrusted', 'Untrusted', 'untrusted bukexin javascript maoxian biancheng alex nisnevich greg shuflin', 'Alex Nisnevich 与 Greg Shuflin', '', '', NULL, '', 0, 2014, 'puzzle', '["解谜","编程","冒险"]', 140, 0.08, 'story', 'https://untrustedgame.com/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '改游戏自己的源码，才能走下去', '一款用 JavaScript 写成的文字冒险：每一关都把关卡源码摊开给你看，你得改代码才能开门、过关。', 'A JavaScript text adventure that shows you each level''s source. You have to edit the code to open doors and advance.', '由 Alex Nisnevich 与 Greg Shuflin 制作，源码以 MIT 许可在 GitHub 发布。原页托管在 untrustedgame.com，不是即玩的作品。在即玩里直接打开原作。进度保存在浏览器本地，开玩不用登录。', 'Made by Alex Nisnevich and Greg Shuflin; the source is MIT-licensed on GitHub. Hosted at untrustedgame.com; it is not a Jiwan original. It opens here. Progress stays in your browser; no account needed.', 'assets/posters/untrusted.jpg', 1280, 800, 'center', '["assets/posters/untrusted.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -27, 1794967200000, 'To go on, you have to edit the game''s own source.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('evolve', 'Evolve', 'Evolve', 'evolve jinhua wenming fangzhi pmotschmann demagorddon', 'Demagorddon (pmotschmann)', '', '', NULL, '', 0, 2019, 'idle', '["放置","策略","文明"]', 30, 0.08, 'clicker', 'https://pmotschmann.github.io/Evolve/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '从原生质一路演化成星际文明', '从原初黏液里的一团原生质开始，收集资源、选择种族、发展科技，把文明一步步带向太空。', 'Start as protoplasm in the primordial ooze, gather resources, pick a race, and research your way to the stars.', '由 Demagorddon（pmotschmann）制作，源码以 MPL-2.0 许可在 GitHub 发布。原页托管在 pmotschmann.github.io/Evolve，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Demagorddon (pmotschmann); the source is MPL-2.0-licensed on GitHub. Hosted at pmotschmann.github.io/Evolve; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/evolve.jpg', 1280, 800, 'center', '["assets/posters/evolve.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -26, 1794967200000, 'Evolve from protoplasm into an interstellar civilization.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('underrun', 'Underrun', 'Underrun', 'underrun dixia paodong sheji phoboslab dominic szablewski', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2018, 'action', '["射击","动作","3D"]', 35, 0.1, 'io', 'https://phoboslab.org/underrun/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在地下走廊里往前冲，别被追上', '一款短小的伪 3D 射击：在逼仄的地下通道里前进、开火，清掉堵路的敌人。', 'A short pseudo-3D shooter: push through tight underground corridors, fire, and clear the enemies in your way.', '由 Dominic Szablewski（Phoboslab）制作，音乐由 Andreas Lösch 创作，源码以 MIT 许可在 GitHub 发布。原页托管在 phoboslab.org/underrun，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab) with music by Andreas Lösch; the source is MIT-licensed on GitHub. Hosted at phoboslab.org/underrun; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/underrun.jpg', 1280, 800, 'center', '["assets/posters/underrun.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -25, 1794967200000, 'Run the underground corridors, and don''t get caught.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('space-huggers', 'Space Huggers', 'Space Huggers', 'space huggers taikong yongbao sheji frank force killedbyapixel', 'Frank Force (KilledByAPixel)', '', '', NULL, '', 0, 2021, 'action', '["射击","动作","像素"]', 200, 0.08, 'io', 'https://killedbyapixel.github.io/SpaceHuggers/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在外星地面上扫清那些热情过度的入侵者', '向 Contra 致敬的像素射击：左右移动、跳跃、开枪，把一波波 Space Huggers 打回去。', 'A Contra-inspired pixel shooter: move, jump and fire to push back waves of Space Huggers.', '由 Frank Force（KilledByAPixel）制作，是 2021 年 js13kGames 的作品，源码以 GPL-3.0 许可在 GitHub 发布。原页托管在 killedbyapixel.github.io/SpaceHuggers，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Frank Force (KilledByAPixel) for js13kGames 2021; the source is GPL-3.0-licensed on GitHub. Hosted at killedbyapixel.github.io/SpaceHuggers; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/space-huggers.jpg', 1280, 800, 'center', '["assets/posters/space-huggers.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -24, 1794967200000, 'Clear the over-friendly invaders off the alien ground.', '', '', 1);
